    funding(){const s=this.state;if(this.month%6!==0)return;const businesses=this.orgs.filter(o=>o.category===1),civics=this.orgs.filter(o=>o.category===0);for(let j=0;j<3;j++){const donor=businesses[Math.floor(this.rand('funder',j)*businesses.length)],target=civics[Math.floor(this.rand('fund-target',j)*civics.length)],leader=this.agents[donor.leader],recipient=this.agents[target.leader],existing=s.funding.find(f=>f.from===donor.id&&f.to===target.id);const d=this.choose(leader,'Funding and influence',[{name:'fund',effects:this.effects([0.1,0.4,0.05],[-.2,.8,.1],[0.1,0.45,0.05]),effort:.05},{name:'withdraw / do not fund',effects:this.effects([0,-0.1,0],[.15,.1,-.1],[0,-0.15,0]),effort:0}],'fund-'+j);if(d.name==='fund'){const response=this.choose(recipient,'Funding conditions',[{name:'accept',effects:this.effects([0.1,0.3,0],[.1,.7,.2],[0.1,0.15,-0.1]),effort:(1-target.editorialIndependence)*.1},{name:'refuse',effects:this.effects([0.05,0.1,0.3],[0,.1,.45],[0,0,0.2]),effort:.04}],'accept-fund-'+j);if(response.name==='accept'){const amount=transfer(donor,target,.8);if(amount){const f=existing||{from:donor.id,to:target.id,total:0,active:true};f.total+=amount;f.payments=(f.payments||[]).filter(x=>this.month-x.month<12);f.payments.push({month:this.month,amount});f.last=this.month;f.active=true;if(!existing)s.funding.push(f);target.editorialIndependence=clamp(target.editorialIndependence-.015);this.link(leader,recipient,true);if(!existing)this.emit('information','A funding relationship develops',donor.name+' funds '+target.name+'. Private funding can create leverage but does not enter the reform implementation pool.',[leader.id,recipient.id],'F-'+donor.id+'-'+target.id,'Funding');}}}else if(existing){existing.active=false;this.emit('information','Funding is withdrawn','The receiving organization must adapt within its own resources.',[leader.id,recipient.id],'F-'+donor.id+'-'+target.id,'Withdrawn');}}}
